1: import { STATUS_TABS, type StatusTab } from '../../../features/review/statusPresentation';
2: import styles from './StatusTabs.module.css';
3: 
4: interface StatusTabsProps {
5:   value: StatusTab;
6:   onChange: (value: StatusTab) => void;
7: }
8: 
9: /** 状态模块三分段切换（今天 / 认知 / 足迹），支持左右方向键切换。 */
10: export function StatusTabs({ value, onChange }: StatusTabsProps) {
11:   function move(step: number) {
12:     const index = STATUS_TABS.findIndex(tab => tab.value === value);
13:     const next = STATUS_TABS[(index + step + STATUS_TABS.length) % STATUS_TABS.length];
14:     onChange(next.value);
15:   }
16:   return <div className={styles.tabs} role="tablist" aria-label="状态分段"
17:     onKeyDown={event => {
18:       if (event.key === 'ArrowRight') { event.preventDefault(); move(1); }
19:       if (event.key === 'ArrowLeft') { event.preventDefault(); move(-1); }
20:     }}>
21:     {STATUS_TABS.map(tab => <button key={tab.value} type="button" role="tab" id={`status-tab-${tab.value}`}
22:       aria-selected={value === tab.value} aria-controls={`status-panel-${tab.value}`} tabIndex={value === tab.value ? 0 : -1}
23:       onClick={() => onChange(tab.value)}>{tab.label}</button>)}
24:   </div>;
25: }

